func Or(predicates ...predicate.CreativeBrief) predicate.CreativeBrief {
	return predicate.CreativeBrief(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CreativeBrief) predicate.CreativeBrief {
	return predicate.CreativeBrief(sql.NotPredicates(p))
}
